/**
 * The contract `tooltip.tsx` (native) and `tooltip.web.tsx` (radix) both
 * implement. Its own module because Metro resolves `./tooltip` to
 * `tooltip.web.tsx` on web.
 *
 * The web half takes radix's props on top of this — `open`/`onOpenChange` on
 * `Tooltip`, `sideOffset`/`align`/`hidden` on the content, the trigger's
 * `<button>` attributes — as shadcn's `tooltip` does, so a DOM call site ports
 * unchanged. Those extras are web only.
 */
import { Children, isValidElement, type ReactNode } from "react";

export type TooltipProviderProps = {
  /** Hover time before a tooltip opens, in ms. Web only — see `tooltip.tsx`. */
  delayDuration?: number | undefined;
  /** Grace period during which a neighbouring tooltip opens instantly. Web only. */
  skipDelayDuration?: number | undefined;
  children: ReactNode;
};

/** Which edge of the trigger the bubble sits on. */
export type TooltipSide = "top" | "right" | "bottom" | "left";

export type TooltipProps = { children: ReactNode };

export type TooltipTriggerProps = {
  /** Hand the handlers to the single child rather than wrapping it. */
  asChild?: boolean | undefined;
  /** The wrapper's class, when not `asChild`. */
  className?: string | undefined;
  children: ReactNode;
};

export type TooltipContentProps = {
  side?: TooltipSide | undefined;
  className?: string | undefined;
  children: ReactNode;
};

/**
 * The tooltip's bubble: the page's colours swapped, so it stands apart from whatever it floats over.
 * It was `bg-secondary`, a raised surface, which in light is all but the page's own white: with
 * only a `/10` edge it melted into the row under it and read as see-through. `foreground` on
 * `background` is the page's own text contrast, in every palette.
 *
 * `max-w-xs`, so a long hint wraps into a short paragraph rather than running the width of the
 * screen in one line (#486).
 */
export const TOOLTIP_CONTENT_CLASS =
  "max-w-xs overflow-hidden rounded-md bg-foreground px-3 py-1.5 shadow-md";
/** The type of the tooltip's text: the page's background colour, on the swapped bubble. */
export const TOOLTIP_TEXT_CLASS = "text-sm text-background";

/**
 * Where the bubble goes on native, per side. Radix measures and flips; there is no
 * collision detection here, so a tooltip near an edge is the caller's `side` to get
 * right — which is the same thing the prop is for on web.
 */
export const TOOLTIP_SIDE_CLASS = {
  top: "bottom-full mb-1 self-center",
  bottom: "top-full mt-1 self-center",
  left: "right-full mr-1 self-start",
  right: "left-full ml-1 self-start",
} as const satisfies Record<TooltipSide, string>;

/** The least time a device's bubble stays up after the finger lifts: long enough for a word. */
const MIN_VISIBLE_MS = 2500;
/**
 * The time a character adds: 60ms is about 170 words a minute, a slow reading pace, so a reader who
 * takes longer than most still reaches the end of a long hint (WCAG 2.2.1).
 */
const MS_PER_CHARACTER = 60;

/** How many characters of text a node holds, through any elements it is made of. */
function textLength(node: ReactNode): number {
  let length = 0;
  Children.forEach(node, (child) => {
    if (typeof child === "string" || typeof child === "number") {
      length += String(child).length;
    } else if (isValidElement<{ children?: ReactNode }>(child)) {
      length += textLength(child.props.children);
    }
  });
  return length;
}

/**
 * How long a device's tooltip stays up once the finger lifts: longer for a longer hint, and never
 * less than {@link MIN_VISIBLE_MS}. The web's stays while it is hovered or focused, and needs none.
 */
export function tooltipVisibleMs(content: ReactNode): number {
  return Math.max(MIN_VISIBLE_MS, textLength(content) * MS_PER_CHARACTER);
}

/**
 * Copied from `registry/ui/tooltip.web.tsx` by `scripts/rn2web`.
 * Do not edit — edit the source and re-run `npm run compile`.
 *
 * This is level 4 of the plan: the item has a hand-written web half, so nothing was generated. The
 * same passes still ran over it, and for a file already written against the DOM they find nothing
 * to do beyond pointing its sibling imports at the web tree. That is deliberate — running one
 * pipeline over the whole output tree is what guarantees a hand-written half and a compiled one
 * speak the same prop vocabulary, instead of the two drifting where nobody is looking.
 */

/**
 * The web tooltip: radix, shown on hover and focus. `tooltip.tsx` is the
 * native counterpart and `tooltip-base.ts` holds the contract they share.
 *
 * Every part also takes the props of the radix part it renders, as shadcn's
 * `tooltip` does — `open`/`onOpenChange`/`delayDuration` on `Tooltip`,
 * `sideOffset`/`align` on the content — so a DOM call site ports unchanged.
 */

import { Tooltip as TooltipPrimitive } from "radix-ui";
import type * as React from "react";
import { createContext, useContext } from "react";
import {
  TOOLTIP_CONTENT_CLASS,
  TOOLTIP_TEXT_CLASS,
  type TooltipContentProps,
  type TooltipProps,
  type TooltipProviderProps,
  type TooltipTriggerProps,
} from "@/components/ui/tooltip-base";
import { CardBodyContext, cn } from "@/lib/utils";

/** The shared contract, widened to what the radix part underneath accepts. */
type Wide<Base, Radix> = Base & Omit<Radix, keyof Base>;

/** Whether a `TooltipProvider` is above. Radix throws without one and has no way to ask. */
const ProvidedContext = createContext(false);

// `delayDuration` defaults to shadcn's `0`, not Radix's 700ms. A tooltip with no provider above
// renders this one, and left to Radix every icon button waited 700ms.
/** Shares the open delay among the tooltips below it. */
function TooltipProvider({
  delayDuration = 0,
  skipDelayDuration,
  ...props
}: Wide<TooltipProviderProps, React.ComponentProps<typeof TooltipPrimitive.Provider>>) {
  return (
    <ProvidedContext.Provider value={true}>
      <TooltipPrimitive.Provider
        {...props}
        delayDuration={delayDuration}
        {...(skipDelayDuration === undefined ? {} : { skipDelayDuration })}
      />
    </ProvidedContext.Provider>
  );
}

/**
 * The root of a tooltip: it holds the open state.
 *
 * It uses the `TooltipProvider` above it, and its timing, when there is one. With none it renders
 * its own, so an installed component can draw a tooltip without the app having set one up.
 */
function Tooltip(props: Wide<TooltipProps, React.ComponentProps<typeof TooltipPrimitive.Root>>) {
  const provided = useContext(ProvidedContext);
  const root = <TooltipPrimitive.Root data-slot="tooltip" {...props} />;
  if (provided) {
    return root;
  }
  return <TooltipProvider>{root}</TooltipProvider>;
}

/** The element the tooltip describes: hovered or focused on the web, long-pressed on device. */
function TooltipTrigger({
  asChild,
  className,
  ...props
}: Wide<TooltipTriggerProps, React.ComponentProps<typeof TooltipPrimitive.Trigger>>) {
  return (
    <TooltipPrimitive.Trigger
      data-slot="tooltip-trigger"
      asChild={asChild ?? false}
      {...(className === undefined ? {} : { className })}
      {...props}
    />
  );
}

/** Kept clear of the window's edge, where radix would otherwise slide the bubble flush with it. */
const COLLISION_PADDING = 8;

/** The tooltip's bubble and its text. */
function TooltipContent({
  side = "top",
  sideOffset = 4,
  collisionPadding = COLLISION_PADDING,
  className,
  children,
  ...props
}: Wide<TooltipContentProps, React.ComponentProps<typeof TooltipPrimitive.Content>>) {
  return (
    <TooltipPrimitive.Portal>
      <TooltipPrimitive.Content
        data-slot="tooltip-content"
        side={side}
        sideOffset={sideOffset}
        collisionPadding={collisionPadding}
        className={cn(
          // `text-balance` evens the lines of a hint that wraps, so the last is not one word.
          "z-50 text-balance animate-in fade-in-0 zoom-in-95 data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=closed]:zoom-out-95 data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2",
          TOOLTIP_CONTENT_CLASS,
          TOOLTIP_TEXT_CLASS,
          className,
        )}
        {...props}
      >
        <CardBodyContext.Provider value={false}>{children}</CardBodyContext.Provider>
      </TooltipPrimitive.Content>
    </TooltipPrimitive.Portal>
  );
}

export { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger };
